# 12 urinary catheter
write(12,"urinary-catheter-care",dict(title="Urinary catheter care", category="elimination-drains", topic_drafts=["D04-T03"],
 evidence_status="partial", license_status="unassessed",
 sources=[src(CAUTI,"full","Recommendation sections I-III read in full text in Phase 7 (2009; PDF footer last update June 2019); other sections not read")],
 objectives=["Describe appropriate indications and the aim of minimising catheter days.","Maintain a closed drainage system and unobstructed flow.","Escalate suspected infection or obstruction."],
 prerequisites=["Infection prevention (SK-21)","Urine output monitoring"],
 sections={
  "indications":sec("full",it("Insert catheters only for appropriate indications and leave them only as long as needed (Category IB). Examples include acute retention or outlet obstruction, accurate urine-output measurement in critically ill patients, and prolonged immobilisation; the indications are expert consensus.","sourced",CAUTI),it("Avoid catheters for managing incontinence (IB); consider external catheters in cooperative men without retention (Category II).","sourced",CAUTI)),
  "safety":sec("full",it("Hand hygiene immediately before and after insertion or any manipulation of the catheter or site (IB).","sourced",CAUTI),it("Only trained persons who know aseptic insertion and maintenance do this (IB); in acute care use aseptic technique and sterile equipment (IB).","sourced",CAUTI),it("Maintain a closed drainage system; if aseptic technique breaks, or the system disconnects or leaks, replace the catheter and collecting system aseptically (IB).","sourced",CAUTI),it("Use Standard Precautions, including gloves and gown as appropriate, during any manipulation (IB).","sourced",CAUTI)),
  "responsibilities":sec("full",it("Secure the catheter to prevent movement and urethral traction (IB); keep the catheter and tubing free from kinking, the bag below bladder level at all times and off the floor (IB); empty the bag regularly with a separate clean container per patient, avoiding splashing and spigot contact (IB).","sourced",CAUTI)),
  "scope":sec("local_protocol",LOCAL("Who inserts, changes and removes catheters, and nurse-led removal protocols, follow local policy.")),
  "equipment":sec("partial",it("Sterile gloves, drape, sponges, an appropriate antiseptic or sterile solution for periurethral cleaning and a single-use lubricant packet for insertion; use the smallest bore catheter consistent with good drainage unless otherwise indicated (IB; II).","sourced",CAUTI)),
  "procedure":sec("local_protocol",LOCAL("The step-by-step insertion sequence is not in the recommendation sections read; follow the competency-approved unit procedure.")),
  "monitoring":sec("partial",it("Do not change catheters or bags at routine fixed intervals; change for infection, obstruction or a compromised closed system (Category II). Do not clean the periurethral area with antiseptics while the catheter is in place; routine hygiene is appropriate (IB).","sourced",CAUTI)),
  "escalation":sec("partial",it("Report fever, new pain, cloudy or blood-stained urine, obstruction or a compromised system; do not give systemic antimicrobials routinely to prevent CAUTI (IB; prescriber decisions).","partial",CAUTI)),
  "complications":sec("partial",it("Catheter-associated urinary tract infection, urethral trauma and obstruction.","partial",CAUTI)),
  "documentation":sec("local_protocol",LOCAL("Record indication, insertion details, daily review of need and removal date per unit standard."))},
 checklist=[c("preparation","Confirm an appropriate indication exists and ask each day whether the catheter is still needed.",True,"sourced",CAUTI),c("preparation","Perform hand hygiene before and after any manipulation.",True,"sourced",CAUTI),c("procedure","Keep the system closed; replace the catheter and system aseptically after a break, disconnection or leak.",True,"sourced",CAUTI),c("procedure","Keep tubing free from kinks and the bag below bladder level and off the floor.",True,"sourced",CAUTI),c("procedure","Secure the catheter to prevent traction.",False,"sourced",CAUTI),c("procedure","Empty the bag with a separate clean container per patient without touching the spigot.",False,"sourced",CAUTI),c("escalation","Report fever, obstruction, cloudy or blood-stained urine.",True,"partial",CAUTI),c("documentation","Record indication, daily review and removal date.",False,"local_protocol")],
 gaps=["Insertion step sequence: not in the sections read.","Specimen collection and removal technique sections: not read in Phase 7.","Critical-care-specific urine-output monitoring detail: see topic D04-T03."],
 permissions=["CDC PDF: no reuse statement on the file; verify before reproducing."],
 references=[ref("Guideline for Prevention of Catheter-Associated Urinary Tract Infections (2009)","CDC/HICPAC",2009,CAUTI and "https://www.cdc.gov/infection-control/media/pdfs/Guideline-CAUTI-H.pdf")]))
